def selector(logical_id: str) -> str:
    try:
        return VALUES[logical_id]
    except KeyError as exc:
        raise RuntimeError(f"selector is unavailable: {logical_id}") from exc


def optional_selector(logical_id: str) -> str | None:
    return VALUES.get(logical_id)
